import pandas as pd

def email_domains(users):
    """Return the lowercased email domain for each user."""
    return users["email"].str.lower().str.split("@").str[-1].rename("domain")

import pandas as pd

def shipping_costs(parcels):
    """Return per-parcel shipping costs (doubled for express)."""

    def cost(row):
        c = 2.0 + 0.5 * row["weight_kg"] + 0.1 * row["distance_km"]
        return c * 2 if row["express"] else c

    return parcels.apply(cost, axis=1).round(2).rename("cost")

import pandas as pd

def category_summary(products, code_to_category):
    """Return ranked category counts with an 'other' bucket."""
    cats = products["code"].map(code_to_category).fillna("other")
    counts = cats.value_counts().rename_axis("category").reset_index(name="count")
    return counts.sort_values(
        ["count", "category"], ascending=[False, True]
    ).reset_index(drop=True)
